    if (sort === "decline") return b.declineFtPerYr - a.declineFtPerYr;
    if (sort === "acres") return b.irrigatedAcresK - a.irrigatedAcresK;
    // years: null (stable) sorts last
    const ay = a.yearsToFloor ?? 9999;
    const by = b.yearsToFloor ?? 9999;
    return ay - by;
  });
}

