                      .filter((c) => c.yearsToFloor !== null)
                      .map((c) => (
                        <Cell
                          key={c.id}
                          fill={
                            (c.yearsToFloor ?? 99) < 25
                              ? ALERT
                              : (c.yearsToFloor ?? 99) < 50
                                ? DRAIN
                                : TEAL
                          }
                        />
                      ))}
                  </Bar>
                </BarChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>
          <ChartCard
            title="Kansas GMD remaining stack"
            subtitle="KGS TS 25 averages ?? years to 30-ft floor at 1996???2022 rates"
          >
            <div className="h-[360px] w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <ComposedChart
                  data={gmds}
                  margin={{ top: 8, right: 16, left: 8, bottom: 8 }}
                >
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis dataKey="name" tick={{ fontSize: 12 }} />
                  <YAxis
                    yAxisId="sat"
                    tick={{ fontSize: 11 }}
                    label={{
                      value: "Sat ft",
                      angle: -90,
                      position: "insideLeft",
                      style: { fontSize: 11, fill: SLATE },
                    }}
                  />
                  <YAxis
                    yAxisId="yr"
                    orientation="right"
                    tick={{ fontSize: 11 }}
                    label={{
                      value: "Years",
                      angle: 90,
                      position: "insideRight",
                      style: { fontSize: 11, fill: SLATE },
                    }}
                  />
                  <Tooltip />
                  <Legend />
                  <Bar
                    yAxisId="sat"
                    dataKey="remainingSatFt"
                    name="Remaining sat (ft)"
                    fill={DEEP}
                    radius={[4, 4, 0, 0]}
                  />
                  <Line
                    yAxisId="yr"
                    type="monotone"
                    dataKey="yearsToFloor"
                    name="Years to floor"
                    stroke={ALERT}
                    strokeWidth={2}
                    dot={{ r: 4 }}
                  />
                </ComposedChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>
        </div>
      )}

      {view === "scatter" && (
        <ChartCard
          title="Decline rate vs years to floor"
          subtitle="Bubble size ??? irrigated acres (thousands) ?? color by High Plains region"
        >
          <div className="h-[400px] w-full min-w-0">
            <ResponsiveContainer width="100%" height="100%">
              <ScatterChart margin={{ top: 12, right: 20, left: 8, bottom: 12 }}>
                <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                <XAxis
                  type="number"
                  dataKey="x"
                  name="Decline"
                  unit=" ft/yr"
                  tick={{ fontSize: 11 }}
                  label={{
                    value: "Decline (ft/yr)",
                    position: "insideBottom",
                    offset: -4,
                    style: { fontSize: 12, fill: SLATE },
                  }}
                />
                <YAxis
                  type="number"
                  dataKey="y"
                  name="Years"
                  tick={{ fontSize: 11 }}
                  label={{
                    value: "Years to 30-ft floor",
                    angle: -90,
                    position: "insideLeft",
                    style: { fontSize: 12, fill: SLATE },
                  }}
                />
                <ZAxis type="number" dataKey="z" range={[60, 400]} />
                <Tooltip
                  cursor={{ strokeDasharray: "3 3" }}
                  formatter={(v: number, name: string) => {
                    if (name === "x" || name === "Decline")
                      return [`${v.toFixed(2)} ft/yr`, "Decline"];
                    if (name === "y" || name === "Years")
                      return [fmtYrs(v > 199 ? null : v), "Years"];
                    return [String(v), name];
                  }}
                  labelFormatter={(_, payload) => {
                    const p = payload?.[0]?.payload;
                    return p ? `${p.label} ?? ${p.irrigatedAcresK}k irrigated ac` : "";
                  }}
                />
                {(
                  [
                    "Southern High Plains",
                    "Central High Plains",
                    "Northern High Plains",
                  ] as const
                ).map((reg) => (
                  <Scatter
                    key={reg}
                    name={reg.replace(" High Plains", "")}
                    data={scatter.filter((d) => d.region === reg)}
                    fill={REGION_COLORS[reg]}
                  />
                ))}
                <Legend />
              </ScatterChart>
            </ResponsiveContainer>
          </div>
        </ChartCard>
      )}

      {view === "states" && (
        <div className="grid gap-6 lg:grid-cols-2">
          <ChartCard
            title="Area-weighted water-level change"
            subtitle="Predevelopment (~1950) ??? 2019 ?? USGS SIR 2023???5143"
          >
            <div className="h-[360px] w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart
                  data={states}
                  margin={{ top: 8, right: 16, left: 8, bottom: 8 }}
                >
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis dataKey="name" tick={{ fontSize: 12 }} />
                  <YAxis
                    tick={{ fontSize: 11 }}
                    label={{
                      value: "ft (decline ???)",
                      angle: -90,
                      position: "insideLeft",
                      style: { fontSize: 11, fill: SLATE },
                    }}
                  />
                  <Tooltip
                    formatter={(v: number, name: string) => [
                      `${name === "declineFt" ? "???" : "+"}${v.toFixed(1)} ft`,
                      name === "declineFt" ? "Decline" : "Rise",
                    ]}
                  />
                  <Bar dataKey="declineFt" name="Decline" stackId="a" fill={ALERT} />
                  <Bar dataKey="riseFt" name="Rise" stackId="a" fill={TEAL} />
                </BarChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>
          <ChartCard
            title="Saturated-thickness loss share of aquifer area"
            subtitle="% of High Plains area by thickness-change band (excl. little/no sat)"
          >
            <div className="h-[360px] w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart
                  data={bands}
                  layout="vertical"
                  margin={{ top: 8, right: 24, left: 8, bottom: 8 }}
                >
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis type="number" unit="%" tick={{ fontSize: 11 }} />
                  <YAxis
                    type="category"
                    dataKey="label"
                    width={150}
                    tick={{ fontSize: 10 }}
                  />
                  <Tooltip
                    formatter={(v: number) => [`${v}% of area`, "Share"]}
                  />
                  <Bar
                    dataKey="pctOfAquiferArea"
                    name="% of area"
                    fill={DEEP}
                    radius={[0, 4, 4, 0]}
                  />
                </BarChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>
        </div>
      )}

      {view === "eras" && (
        <ChartCard
          title="Cumulative area-weighted decline path"
          subtitle="Illustrative era milestones ?? 2019 endpoint = USGS ???16.5 ft"
        >
          <div className="h-[380px] w-full min-w-0">
            <ResponsiveContainer width="100%" height="100%">
              <ComposedChart
                data={eras}
                margin={{ top: 8, right: 16, left: 8, bottom: 8 }}
              >
                <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                <XAxis dataKey="year" tick={{ fontSize: 12 }} />
                <YAxis
                  tick={{ fontSize: 11 }}
                  label={{
                    value: "Cumulative decline (ft)",
                    angle: -90,
                    position: "insideLeft",
                    style: { fontSize: 11, fill: SLATE },
                  }}
                />
                <Tooltip
                  formatter={(v: number) => [`${v.toFixed(1)} ft`, "Cumulative"]}
                  labelFormatter={(y) => `Year ${y}`}
                />
                <Bar
                  dataKey="areaWeightedDeclineFtCumulative"
                  name="Cumulative decline"
                  fill={DRAIN}
                  opacity={0.35}
                  radius={[4, 4, 0, 0]}
                />
                <Line
                  type="monotone"
                  dataKey="areaWeightedDeclineFtCumulative"
                  name="Path"
                  stroke={ALERT}
                  strokeWidth={2.5}
                  dot={{ r: 4, fill: ALERT }}
                />
              </ComposedChart>
            </ResponsiveContainer>
          </div>
        </ChartCard>
      )}

      <p className="text-xs leading-relaxed text-slate-500">{SOURCE_NOTE}</p>
    </div>
  );
}

